'use strict';

// MODULES //

var normalLogcdf = require( '@stdlib/stats-base-dists-normal-logcdf' );
var log1pexp = require( '@stdlib/math-base-special-log1pexp' );
var isnan = require( '@stdlib/math-base-assert-is-nan' );
var sqrt = require( '@stdlib/math-base-special-sqrt' );
var PINF = require( '@stdlib/constants-float64-pinf' );
var NINF = require( '@stdlib/constants-float64-ninf' );


// MAIN //

/**
* Evaluates the natural logarithm of the cumulative distribution function (CDF) for a Wald distribution with mean `mu` and shape parameter `lambda` at a value `x`.
*
* @param {number} x - input value
* @param {PositiveNumber} mu - mean
* @param {NonNegativeNumber} lambda - shape parameter
* @returns {number} evaluated logCDF
*
* @example
* var y = logcdf( 2.0, 1.0, 1.0 );
* // returns ~-0.122
*
* @example
* var y = logcdf( 0.5, 2.0, 3.0 );
* // returns ~-2.897
*
* @example
* var y = logcdf( NaN, 1.0, 1.0 );
* // returns NaN
*
* @example
* var y = logcdf( 1.0, NaN, 1.0 );
* // returns NaN
*
* @example
* var y = logcdf( 1.0, 1.0, NaN );
* // returns NaN
*
* @example
* // Non-positive mean:
* var y = logcdf( 2.0, 0.0, 1.0 );
* // returns NaN
*
* @example
* // Negative shape parameter:
* var y = logcdf( 2.0, 1.0, -1.0 );
* // returns NaN
*
* @example
* // Zero shape parameter (degenerate distribution):
* var y = logcdf( 1.0, 1.0, 0.0 );
* // returns 0.0
*
* @example
* var y = logcdf( 0.0, 1.0, 1.0 );
* // returns -Infinity
*/
function logcdf( x, mu, lambda ) {
	var a;
	var b;
	var v;
	var z;

	if (
		isnan( x ) ||
		isnan( mu ) ||
		isnan( lambda ) ||
		mu <= 0.0 ||
		lambda < 0.0
	) {
		return NaN;
	}
	if ( lambda === 0.0 ) {
		return ( x < mu ) ? NINF : 0.0;
	}
	if ( x <= 0.0 ) {
		return NINF;
	}
	if ( x === PINF ) {
		return 0.0;
	}
	z = sqrt( lambda / x );
	v = x / mu;

	// First term: ln( Φ( √(λ/x)·(x/μ-1) ) ):
	a = normalLogcdf( z * ( v - 1.0 ), 0.0, 1.0 );

	// Second term, in log-space to avoid overflow of exp( 2λ/μ ):
	b = ( ( 2.0 * lambda ) / mu ) + normalLogcdf( -z * ( v + 1.0 ), 0.0, 1.0 );

	// Sum the terms in log-space: ln( e^a + e^b ) = a + ln( 1 + e^(b-a) ):
	return a + log1pexp( b - a );
}


// EXPORTS //

module.exports = logcdf;
